sparql:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?Presentation_1 ?Presentation_1_label WHERE {
  ?Presentation_1 rdf:type <http://data.esante.gouv.fr/ansm/medicament/Presentation>.
  OPTIONAL { ?Presentation_1 rdfs:label ?Presentation_1_label. }
  ?Presentation_1 rdfs:label ?Text.
  FILTER(REGEX(STR(?Text), "multidose", "i"))
  ?Presentation_1 <http://data.esante.gouv.fr/ansm/medicament/presente> ?SpecialitePharmaceutique.
  ?SpecialitePharmaceutique rdf:type <http://data.esante.gouv.fr/ansm/medicament/SpecialitePharmaceutique>;
    <http://data.esante.gouv.fr/ansm/medicament/voie> ?Voie.
  VALUES ?Voie {
    <http://data.esante.gouv.fr/ansm/medicament/Voie_13>
    <http://data.esante.gouv.fr/ansm/medicament/Voie_16>
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?Presentation_1 ?Presentation_1_label ?Substance_4 ?Substance_4_label ?TypeProcedure_6 ?TypeProcedure_6_label WHERE {
  ?Presentation_1 rdf:type <http://data.esante.gouv.fr/ansm/medicament/Presentation>.
  OPTIONAL { ?Presentation_1 rdfs:label ?Presentation_1_label. }
  ?Presentation_1 <http://data.esante.gouv.fr/ansm/medicament/presente> ?SpecialitePharmaceutique.
  ?SpecialitePharmaceutique rdf:type <http://data.esante.gouv.fr/ansm/medicament/SpecialitePharmaceutique>;
    <http://data.esante.gouv.fr/ansm/medicament/substanceActive> ?Substance_4.
  OPTIONAL { ?Substance_4 rdfs:label ?Substance_4_label. }
  VALUES ?Substance_4 {
    <http://data.esante.gouv.fr/ansm/medicament/Substance_73242>
  }
  ?SpecialitePharmaceutique <http://data.esante.gouv.fr/ansm/medicament/typeProcedureCourante> ?TypeProcedure_6.
  OPTIONAL {
    ?TypeProcedure_6 rdfs:label ?TypeProcedure_6_label.
    FILTER((LANG(?TypeProcedure_6_label)) = "fr")
  }
  VALUES ?TypeProcedure_6 {
    <http://data.esante.gouv.fr/ansm/medicament/TypeProcedure_31>
  }
}
